from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.cu import pages


class Dashboard(pages.Dashboard):
    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Dashboard, self).__init__(driver, version)
            self._instance_dict.update(
                {"Dashboard": DashboardPageV25R1(driver, version)})


class DashboardPageV25R1(pages.DashboardPage):

    MENU_ROUTE_LIST = ['view-dashboard', 'Dashboard']
